INSERT INTO workoutapp.exercise (name, muscle_group, description) VALUES
('Стойка на руках', 'Плечи, Пресс', 'Стойка на руках — гимнастическое упражнение, при котором тело удерживается в вертикальном положении вверх ногами с опорой на кисти рук. Развивает силу плечевого пояса, корпуса, чувство баланса и координацию.'),
('Подтягивания широким хватом', 'Спина, Предплечья', 'Подтягивания широким хватом — базовое упражнение с собственным весом, при котором выполняется подтягивание на перекладине широким хватом. Основная нагрузка приходится на широчайшие мышцы спины, также работают бицепсы, мышцы предплечий и плечевого пояса. Развивает силу верхней части тела и ширину спины.'),
('Подтягивания на бицепс', 'Бицепс, Предплечья', 'Подтягивания на бицепс — упражнение с собственным весом, выполняемое обратным хватом (ладони к себе), при котором тело подтягивается к перекладине за счёт сгибания рук. Основная нагрузка приходится на бицепсы, также работают мышцы спины и предплечий. Развивает силу рук и верхней части тела.'),
('Удержание тела на перекладине', 'Сила хвата', 'Удержание тела на перекладине — статическое упражнение, при котором тело фиксируется в определённом положении с помощью силы хвата и мышц верхней части тела. Развивает выносливость предплечий, силу хвата, плечевого пояса и мышц корпуса.'),
('Отжимания', 'Грудь', 'Отжимания — базовое упражнение с собственным весом, при котором тело опускается и поднимается за счёт сгибания и разгибания рук в упоре лёжа. Основная нагрузка приходится на грудные мышцы, трицепсы и переднюю часть плеч. Развивает силу верхней части тела и выносливость.'),
('Брусья', 'Трицепс', 'Отжимания на брусьях — силовое упражнение с собственным весом, при котором тело опускается и поднимается между параллельными перекладинами. Основная нагрузка приходится на грудные мышцы, трицепсы и переднюю часть плеч. Развивает силу верхней части тела.'),
('Подъём корпуса в упоре на брусьях', 'Пресс', 'Подъём корпуса в упоре на брусьях — упражнение для мышц пресса, выполняемое в положении упора на локтях на брусьях с подъёмом корпуса или таза за счёт сокращения мышц живота. Основная нагрузка приходится на прямую и косые мышцы пресса. Развивает силу и выносливость мышц корпуса.');
